var GLITCH_MAP={'a':'ａ','e':'ｅ','o':'ｏ','s':'ｓ','i':'ı','l':'ℓ','t':'𝚝','A':'Ａ','E':'Ｅ','O':'Ｏ','S':'Ｓ','I':'𝙸','L':'𝙻','T':'𝚃','c':'𝚌','C':'𝙲','u':'𝚞','U':'𝚄'};
function glitch(text, opts){
  opts=opts||{}; var intensity=opts.intensity==null?1:opts.intensity;
  if(intensity<=0) return text;
  var out='';
  for(var i=0;i<text.length;i++){
    var c=text[i], r=GLITCH_MAP[c];
    if(r && Math.random()<(0.3*intensity)) out+=r; else out+=c;
    if(intensity>=2 && c!==' ' && Math.random()<0.18) out+='̷';
  }
  return out;
}
var EXPORTS={glitch:glitch,GLITCH_MAP:GLITCH_MAP};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GlitchForgePure = EXPORTS; }
